def imputar_pagos_existentes(apps, schema_editor):
    """Los pagos ya validados cancelaban capital de su propio período: se registran así."""
    Pago = apps.get_model('gastos', 'Pago')
    ImputacionPago = apps.get_model('gastos', 'ImputacionPago')
    cancelado = {}
    for pago in Pago.objects.filter(estado='validado').select_related('detalle_liquidacion').order_by('fecha_pago', 'pk'):
        detalle = pago.detalle_liquidacion
        capital = min(pago.monto_pagado, detalle.monto_total - cancelado.get(detalle.pk, 0))
        if capital > 0:
            ImputacionPago.objects.create(pago=pago, detalle_liquidacion=detalle, concepto='capital', monto=capital)
            cancelado[detalle.pk] = cancelado.get(detalle.pk, 0) + capital
        if pago.monto_pagado > capital:
            ImputacionPago.objects.create(pago=pago, concepto='excedente', monto=pago.monto_pagado - capital)


